.app-layout {
  min-block-size: 100dvh;
  background: var(--muted);
  color: var(--foreground);
}

/* Nav and content are ONE composition, so the cap belongs to the pair rather
 * than to the content alone: capping only the content leaves the nav against
 * the screen edge and the content column reading right of centre (measured at
 * 2560: 130px off). The surface above still fills the screen, so the margins
 * read as page, not as a hole. */
.app-layout-inner {
  display: grid;
  grid-template-columns: auto 1fr;
  min-block-size: 100dvh;
  inline-size: 100%;
  max-inline-size: var(--shell-max-width);
  margin-inline: auto;
}
.app-layout-nav { position: sticky; inset-block-start: 0; block-size: 100dvh; }
.app-layout-main { min-inline-size: 0; }

/* A page whose columns scroll on their own needs the SHELL to stop scrolling first: two nested
 * scrollers, one of them the document, means the inner one only starts moving after the outer
 * has run out, which is the opposite of the intent. Keyed on the page's own opt-in
 * (`[data-panels]`) rather than on a route, so the shell knows nothing about which screens do
 * this. Desktop only — the panelled layout itself only exists from 62rem up. */
@media (min-width: 62rem) {
  .app-layout:has([data-panels]) { block-size: 100dvh; overflow: hidden; }
  .app-layout:has([data-panels]) .app-layout-inner { block-size: 100dvh; min-block-size: 0; }
  .app-layout:has([data-panels]) .app-layout-main {
    min-block-size: 0;
    display: flex;
    flex-direction: column;
  }
}

/* Mobile: nav becomes an overlay drawer. */
@media (max-width: 48rem) {
  .app-layout-inner { grid-template-columns: 1fr; }
  /* `top` keeps its bar and `none` has nothing to slide, so only the two side
     arrangements turn into a drawer. */
  .app-layout[data-arrangement='rail'] .app-layout-nav,
  .app-layout[data-arrangement='float'] .app-layout-nav {
    position: fixed; inset-block: 0; inset-inline-start: 0; z-index: var(--z-modal);
    background: var(--card); box-shadow: var(--shadow-lg);
    transform: translateX(-100%); transition: transform var(--duration-normal);
  }
  .app-layout[data-nav-open] .app-layout-nav { transform: translateX(0); }
  .app-layout-backdrop {
    position: fixed; inset: 0; z-index: var(--z-sticky);
    border: 0; padding: 0; background: var(--overlay); cursor: pointer;
  }
}

/* ── Where the navigation sits ───────────────────────────────────────────────
 * `rail` is the default and is everything above: a column attached to the
 * content, the pair capped and centred together. */

/* Detached: the nav is a card with air around it and the page surface runs
 * under it. The gap is the whole difference, so it is the only thing declared —
 * the column, the stickiness and the cap are still the rail's. */
.app-layout[data-arrangement='float'] .app-layout-inner {
  gap: var(--space-4);
  padding: var(--space-4);
}
.app-layout[data-arrangement='float'] .app-layout-nav {
  block-size: calc(100dvh - var(--space-8));
  inset-block-start: var(--space-4);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--card);
  box-shadow: var(--shadow-sm);
}

/* A bar above the content and no side column. A shallow navigation earns this:
 * a rail holding four links spends a sixth of the screen saying very little. */
.app-layout[data-arrangement='top'] .app-layout-inner {
  grid-template-columns: 1fr;
  grid-template-rows: auto 1fr;
}
.app-layout[data-arrangement='top'] .app-layout-nav {
  position: sticky;
  inset-block-start: 0;
  block-size: auto;
  z-index: var(--z-sticky);
  background: var(--card);
  border-block-end: 1px solid var(--border);
}

/* No navigation: the content is the whole composition. */
.app-layout[data-arrangement='none'] .app-layout-inner {
  grid-template-columns: 1fr;
}

import "./AppLayout.css";
import { type ReactNode } from "react";

/**
 * Where the navigation sits, and it is a real choice rather than a skin.
 *
 * `rail` is a column attached to the content: the two read as one composition
 * and the page surface runs behind both. `float` detaches it into a card with
 * air around it, which suits a product whose pages are documents rather than
 * desks. `top` is a horizontal bar and no side column, which is what a shallow
 * navigation earns — a side rail holding four links spends a sixth of the
 * screen saying very little. `none` is a screen with no navigation at all:
 * sign-in, a status page, a focused reading view.
 */
type Arrangement = 'rail' | 'float' | 'top' | 'none';

type Props = {
  /** The navigation (e.g. a <SideNav/>). Ignored when `layout` is "none". */
  nav?: ReactNode;
  children: ReactNode;
  /** How the shell is arranged: where the navigation sits, and whether it is attached to the content or detached from it. */
  arrangement?: Arrangement;
  /** Mobile only: whether the nav drawer is open. */
  navOpen?: boolean;
  /** Mobile only: called when the backdrop is clicked. */
  onNavClose?: () => void;
};

/** The application shell: navigation and a scrolling main, in one of four
 *  arrangements. Routing-agnostic — pass any nav in the `nav` slot. Below the
 *  drawer breakpoint a side arrangement becomes an overlay drawer toggled by
 *  `navOpen`; `top` and `none` have nothing to drawer and stay as they are. */
export function AppLayout({ nav, children, arrangement = 'rail', navOpen, onNavClose }: Props) {
  const showNav = arrangement !== 'none' && !!nav;
  return (
    <div className="app-layout" data-arrangement={arrangement} data-nav-open={(navOpen && showNav) || undefined}>
      {navOpen && showNav && (
        <button type="button" className="app-layout-backdrop" aria-label="Close menu" onClick={onNavClose} />
      )}
      {/* The cap lives on this inner track, not on the outer element, so the page
        * surface still reaches both screen edges while the composition itself
        * stops growing and centres. Capping the content column alone leaves the
        * nav against the edge and the content reading right of centre. */}
      <div className="app-layout-inner">
        {/* One control, in the shell, so no screen has to remember it. */}
        {showNav && <div className="app-layout-nav">{nav}</div>}
        <main id="main" className="app-layout-main">{children}</main>
      </div>
    </div>
  );
}
